// Рядки блоку зверху вниз. Relative: режим · чотири пороги відкриття ·
// заголовок закриття · на кожну сторону вмикач і два пороги. Legacy: режим ·
// мінімальна точність · заголовок · два вмикачі (Legacy закриває будь-яким
// сигналом — порогів немає).
export const neuronPreferencesLayout = (t, mode, scales) => {
    const isRelative = mode === 'relative';
    const withSteps = (floor) => ({
        ...floor,
        hasSteps: scales.has(floor.scale),
    });
    const rows = [
        { kind: 'spinner', key: 'trade_accuracy_mode', label: t('Accuracy mode') },
        ...(isRelative
            ? openingFloors(t).map(withSteps)
            : [{
                    kind: 'spinner',
                    key: 'minimal_accuracy',
                    label: t('Minimum accuracy, Value in %'),
                }]),
        { kind: 'title', key: 'reverse_close_title', label: t('Close on a reverse signal') },
    ];
    reverseCloseGroups(t).forEach((group) => {
        rows.push({ kind: 'spinner', key: group.toggle, label: group.label });
        if (isRelative)
            rows.push(...group.floors.map(withSteps));
    });
    return rows;
};
// Перший візит: типові значення бекенду — Relative, нейрон зі шкалами.
export const DEFAULT_NEURON_LAYOUT_HINT = {
    mode: 'relative',
    scales: [...NEURON_SCALE_KEYS],
    noScaleWarning: null,
};
const isHint = (value) => {
    if (typeof value !== 'object' || value === null)
        return false;
    const hint = value;
    return (hint.mode === 'relative' || hint.mode === 'legacy')
        && Array.isArray(hint.scales)
        && hint.scales.every((key) => NEURON_SCALE_KEYS.includes(key))
        && (hint.noScaleWarning === null || typeof hint.noScaleWarning === 'string')
        && (hint.neuronLine == null || typeof hint.neuronLine === 'string');
};
// Сховище може бути недоступне (приватний режим) або містити сміття — тоді
// типова форма.
export const readNeuronLayoutHint = () => {
    try {
        const raw = localStorage.getItem(LS_NEURON_PREFERENCES_LAYOUT);
        const parsed = raw ? JSON.parse(raw) : null;
        return isHint(parsed) ? parsed : DEFAULT_NEURON_LAYOUT_HINT;
    }
    catch {
        return DEFAULT_NEURON_LAYOUT_HINT;
    }
};
export const writeNeuronLayoutHint = (hint) => {
    try {
        localStorage.setItem(LS_NEURON_PREFERENCES_LAYOUT, JSON.stringify(hint));
    }
    catch {
        // без сховища наступна заглушка візьме типову форму
    }
};
